import{_ as s,a0 as l,w as u,s as p,ao as n,I as a,x as o,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"故障排除提示：5 个最常见的 Linux 问题 | LCTT x X-CMD","titleTemplate":false,"description":"故障排除提示：5 个最常见的 Linux 问题 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"故障排除提示：5 个最常见的 Linux 问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"故障排除提示：5 个最常见的 Linux 问题 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170109 Troubleshooting tips for the 5 most common Linux issues","title":"故障排除提示：5 个最常见的 Linux 问题","tag":"201702","desc":""},"relativePath":"201702/20170109 Troubleshooting tips for the 5 most common Linux issues.md","filePath":"[post].md"}'),m={name:"201702/20170109 Troubleshooting tips for the 5 most common Linux issues.md"};function d(x,e,f,L,h,b){const t=l("Link");return u(),p("div",null,[e[16]||(e[16]=n('<h1 id="故障排除提示-5-个最常见的-linux-问题" tabindex="-1">故障排除提示：5 个最常见的 Linux 问题 <a class="header-anchor" href="#故障排除提示-5-个最常见的-linux-问题" aria-label="Permalink to “故障排除提示：5 个最常见的 Linux 问题”">​</a></h1><blockquote><p>了解如何解决Linux桌面用户遇到的最常见的问题</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/law/rh_003601_05_mech_osyearbook2016_containers_cc.png?itok=0ZEfXLEE" alt="5个linux最常见问题解决提示" title="Troubleshooting tips for the 5 most common Linux issues"></p><p>图片：Opensource.com</p><p>尽管绝大多数用户如预期地成功安装和操作了 Linux， 但不可避免地仍会有一些用户遇到问题。作为今年任务队列里的最后一篇文章，我认为在即将进入 2016 年时，总结一下人们所遇到的最常见的技术性的 Linux 问题会很有趣。我把这个问题发布到了 LinuxQuestions.org（LQ） 和社交媒体，我分析了 LQ 的帖子情况之后，得到如下成果。</p><h3 id="_1、-wifi-驱动程序-特别是-broadcom-芯片" tabindex="-1">1、 Wifi 驱动程序（特别是 Broadcom 芯片） <a class="header-anchor" href="#_1、-wifi-驱动程序-特别是-broadcom-芯片" aria-label="Permalink to “1、 Wifi 驱动程序（特别是 Broadcom 芯片）”">​</a></h3><p>一般来说，Wifi 驱动程序，特别是 Broadcom 无线网卡，仍然是 Linux 面临的最大的问题技术问题之一。在 LQ 上，2016 年有数以百计的帖子在讨论这个话题，而且还有其他无数的地方也是。市场上有数十种 Broadcom 无线网卡可供使用，但为每一个发行版描述具体的排错细节来已经超出了一篇文章的范畴，但是基本的故障排除步骤是相同的：</p><ul><li>通过使用 <code>lspci</code> 命令确定具体使用的 Broadcom 卡，以找出 PCI ID，</li><li>确定使用发行版是否支持该卡，</li><li>如果支持，找到正确的方法来使网卡工作。</li></ul><p>例如，如果有一个 <code>14e4:4315</code> PCI ID 的卡，并且系统为 Ubuntu，则应该知道 BCM4312 卡可以通过安装 <code>firmware-b43-installer</code> 包来驱动。另一个选择是在购买之前，研究好可用的 WiFi 卡，以确保您的发行版完全支持它。</p><h3 id="_2、-打印机驱动程序-特别是佳能和-lexmark" tabindex="-1">2、 打印机驱动程序（特别是佳能和 Lexmark） <a class="header-anchor" href="#_2、-打印机驱动程序-特别是佳能和-lexmark" aria-label="Permalink to “2、 打印机驱动程序（特别是佳能和 Lexmark）”">​</a></h3>',10)),a("p",null,[e[1]||(e[1]=o("打印机也是常有问题的，佳能和 Lexmark 被反复提及遇到这种问题。如果您要购买一台新打印机，请在购买之前研究兼容性。但是，如果您从其他操作系统迁移，这可能没得选择。如果你正在做调研，",-1)),i(t,{href:"http://www.openprinting.org/printers"},{default:r(()=>[...e[0]||(e[0]=[o("OpenPrinting",-1)])]),_:1}),e[2]||(e[2]=o(" 数据库和您的发行版的官方支持渠道是两个最好的起点。请注意，您应确保设备的所有功能完全兼容，特别是如果它是个多功能产品。对佳能打印机的一个常见的抱怨是，驱动程序通常只能在非英语，甚至是很难找的网站上才有。",-1))]),e[17]||(e[17]=n('<blockquote><p>如果您购买的是新打印机，请在购买之前研究兼容性。</p></blockquote><h3 id="_3、-显卡" tabindex="-1">3、 显卡 <a class="header-anchor" href="#_3、-显卡" aria-label="Permalink to “3、 显卡”">​</a></h3><p>显卡是一个微妙的话题，因为在 Linux 上显卡可以非常好的简单直观的开箱即用。出现的问题是：显卡加速器/3D 加速；最新的显卡和最新显示技术，如 NVIDIA Optimus 和 ATI 动态 GPU 切换；专有驱动程序的安装和稳定性；能效管理；以及可靠的挂起和恢复。如果你不是一个游戏玩家，也没有别的需要高端图形功能的需求，并且不是使用笔记本电脑，那么你可能不必担心这个。如果您正在寻找一台新的笔记本电脑，一定要在购买前研究好兼容性。如果你是一个游戏玩家或需要最高端的图形功能，你需要明确知道你的需求是什么，然后开始你的研究。幸运的是，这种情况正在改善，Wayland 开始解决问题，2017 年情况应该会变得好一些。</p><h3 id="_4、-声卡" tabindex="-1">4、 声卡 <a class="header-anchor" href="#_4、-声卡" aria-label="Permalink to “4、 声卡”">​</a></h3><p>再次，对于简单配置，声卡非常容易设置并可以很可靠地在 Linux 上运行。一旦你买的是专业级产品，例如回声消除、音频路由，统一混合和其他复杂的配置，它可能就很快地每况愈下。我的建议是，如果你需要高端的实时音频，请使用专用的音频相关的发行版。</p><h3 id="_5、-安装" tabindex="-1">5、 安装 <a class="header-anchor" href="#_5、-安装" aria-label="Permalink to “5、 安装”">​</a></h3><p>有了这个包罗万象的分类，本文几乎保证是高质量的。也就是说，公平的说，我不知道 Linux 有普遍的安装问题。绝大多数的安装都按预期进行。Linux 支持多种硬件，安装 Linux 机器上可能有近乎无限的硬件组合，不可避免会导致了某种情况下的例外情况。最终用户其实也很少安装类似 Mac OS 或 Windows 这样的其它系统，因为它们都是随同新设备预安装的。</p><blockquote><p>绝大多数的安装都按预期进行。</p></blockquote><h3 id="前景光明" tabindex="-1">前景光明 <a class="header-anchor" href="#前景光明" aria-label="Permalink to “前景光明”">​</a></h3><p>其他提到的问题经常包括蓝牙、挂起/恢复，HiDPI 和触摸屏。您可能会看到这里形成一个模式，本文中提到的大多数问题集中在桌面用户。如果你已经意识到了这点，这其实是有意义的。Linux 桌面使用率相对较低，导致结果是，用于发现和解决相关问题的测试和资源很少。随着桌面使用量的增加，可以预期这些部分会改善。</p><p>在这方面，我认为最好提及的一个例子，曾经常常作为 Linux 的问题提出，但是反而最近很罕见：字体。几年前，获得高品质的抗锯齿字体常常是个问题。但是，随着现代发行版本的更新，它已成为常规。</p><p>你认为 2016 年最常见的 Linux 技术问题是什么？ 请在评论中留言告诉我。</p><hr><p>作者简介：</p><p><img src="https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/jeremy-garcia.jpg?itok=kqOMWJIg" alt=""></p><p>Jeremy Garcia - Jeremy Garcia is the founder of LinuxQuestions.org and an ardent but realistic open source advocate. Follow Jeremy on Twitter: @linuxquestions</p><hr>',17)),a("p",null,[e[4]||(e[4]=o("via: ",-1)),i(t,{href:"https://opensource.com/article/17/1/yearbook-linux-troubleshooting-tips"},{default:r(()=>[...e[3]||(e[3]=[o("https://opensource.com/article/17/1/yearbook-linux-troubleshooting-tips",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("作者：",-1)),i(t,{href:"https://opensource.com/users/jeremy-garcia"},{default:r(()=>[...e[5]||(e[5]=[o("Jeremy Garcia",-1)])]),_:1}),e[9]||(e[9]=o(" 译者：",-1)),i(t,{href:"http://vicyu.net"},{default:r(()=>[...e[6]||(e[6]=[o("Vic020",-1)])]),_:1}),e[10]||(e[10]=o(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=o("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[o("Linux中国",-1)])]),_:1}),e[15]||(e[15]=o(" 荣誉推出",-1))])])}const g=s(m,[["render",d]]);export{c as __pageData,g as default};
